namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
San Marzano tomatoes
Fresh mozzarella
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F.
2. Roll out dough on floured surface.
3. Spread crushed tomatoes evenly.
4. Tear mozzarella and distribute.
5. Bake 10-12 minutes until crust is golden.
6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Garam masala
Turmeric
Cumin
Tomato sauce
Heavy cream
Garlic
Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.
2. Grill or broil chicken until charred.
3. Sauté garlic and ginger in oil.
4. Add tomato sauce and spices, simmer 15 min.
5. Add cream and cooked chicken.
6. Simmer 10 more minutes. Serve with rice.", AverageRating = 4.8, RatingCount = 24 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in a skillet.
2. Add taco seasoning and water, simmer 5 min.
3. Warm tortillas in a dry pan.
4. Assemble tacos with beef and toppings.
5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles
Shrimp or tofu
Bean sprouts
Eggs
Peanuts
Lime
Fish sauce
Tamarind paste
Garlic", Steps = "1. Soak rice noodles in warm water 30 min.
2. Stir-fry garlic and shrimp/tofu.
3. Push aside, scramble eggs in pan.
4. Add drained noodles, tamarind, fish sauce.
5. Toss with bean sprouts.
6. Serve with crushed peanuts and lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "French Onion Soup", Category = "French", Ingredients = "Yellow onions
Butter
Beef broth
White wine
Thyme
Bay leaf
Baguette
Gruyère cheese", Steps = "1. Slice onions thinly and caramelize in butter (45 min).
2. Deglaze with white wine.
3. Add broth, thyme, bay leaf. Simmer 20 min.
4. Ladle into oven-safe bowls.
5. Top with baguette slices and Gruyère.
6. Broil until cheese is bubbly and golden.", AverageRating = 4.4, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook pasta in salted water until al dente.
2. Crisp guanciale in a pan.
3. Whisk eggs with grated pecorino and pepper.
4. Toss hot pasta with guanciale off heat.
5. Quickly stir in egg mixture (residual heat cooks it).
6. Serve immediately with extra pecorino.", AverageRating = 4.7, RatingCount = 19 },
    };

    private int _nextId = 7;

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void Submit(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

