@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hovered ? "hovered" : "") @(star <= _selected ? "selected" : "")"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = 0"
              @onclick="() => SubmitRating(star)">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks! You rated @_selected star@(_selected > 1 ? "s" : "").</span>
    }
</div>

<style>
    .star-rating { display: flex; align-items: center; gap: 4px; margin: 1rem 0; }
    .star { font-size: 1.8rem; cursor: pointer; color: #ccc; transition: color 0.15s; }
    .star.hovered, .star.selected { color: #f5a623; }
    .rating-label { margin-right: 0.5rem; font-weight: 500; }
    .rating-thanks { margin-left: 0.75rem; color: #28a745; font-weight: 500; }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private int _hovered;
    private int _selected;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selected = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

