toolArgs.file_text:
@page "/category/{CategoryName}"
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet.</div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in _recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">
                                <a href="/recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                            </h4>
                            <p class="text-warning mb-1">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <span class="text-muted ms-2">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</span>
                            </p>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<RecipeCommunity.Models.Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeCommunity.Services.RecipeService RecipeService
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe Not Found")</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-2">@_recipe.Title</h1>
        <p class="text-muted">Category: <a href="/category/@_recipe.Category">@_recipe.Category</a></p>

        <div class="mb-3">
            <span class="text-warning fs-5">
                @for (int i = 1; i <= 5; i++)
                {
                    <span>@(i <= (int)Math.Round(_recipe.AverageRating) ? "★" : "☆")</span>
                }
            </span>
            <span class="text-muted ms-2">@_recipe.AverageRating / 5 (@_recipe.RatingCount ratings)</span>
        </div>

        <StarRating RecipeId="@_recipe.Id" />

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">🥗 Ingredients</h5></div>
                    <div class="card-body">
                        <ul class="list-unstyled mb-0">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p class="mb-2">@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeCommunity.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@_model.Title</strong>" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label class="form-label fw-bold">Recipe Title</label>
                <InputText @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-bold">Category</label>
                <InputSelect @bind-Value="_model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Thai">Thai</option>
                    <option value="French">French</option>
                    <option value="American">American</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label fw-bold">Ingredients</label>
                <InputTextArea @bind-Value="_model.Ingredients" class="form-control" rows="6" placeholder="One ingredient per line" />
                <div class="form-text">Enter one ingredient per line.</div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-bold">Steps</label>
                <InputTextArea @bind-Value="_model.Steps" class="form-control" rows="8" placeholder="Describe each step..." />
                <div class="form-text">Number each step (e.g., "1. Preheat oven...").</div>
            </div>

            <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsValid)">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeCommunity.Models.RecipeSubmission _model = new();
    private bool _submitted;

    private bool IsValid => !string.IsNullOrWhiteSpace(_model.Title)
                         && !string.IsNullOrWhiteSpace(_model.Category)
                         && !string.IsNullOrWhiteSpace(_model.Ingredients)
                         && !string.IsNullOrWhiteSpace(_model.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.Submit(_model);
        _submitted = true;
    }
}

